-- [[ BITWISE UTILITIES FOR DESERIALIZATION ]] --
local function bitAnd(a, b)
    local result = 0
    local bitval = 1
    while a > 0 and b > 0 do
        if a % 2 == 1 and b % 2 == 1 then
            result = result + bitval
        end
        bitval = bitval * 2
        a = math.floor(a / 2)
        b = math.floor(b / 2)
    end
    return result
end

local function readString(stream, pos, len)
    return string.sub(stream, pos, pos + len - 1), pos + len
end

local function readInt8(stream, pos)
    local b = string.byte(stream, pos)
    return b, pos + 1
end

local function readInt16(stream, pos)
    local b1, b2 = string.byte(stream, pos, pos + 1)
    return (b1 * 256) + b2, pos + 2
end

local function readInt32(stream, pos)
    local b1, b2, b3, b4 = string.byte(stream, pos, pos + 3)
    return (b1 * 16777216) + (b2 * 65536) + (b3 * 256) + b4, pos + 4
end

local function readFloat64(stream, pos)
